mapper.select:
        SELECT DATE_FORMAT(execute_time ${timeFormat} ${timeFlag},
               SUM(IFNULL(task_state = 240, 0)) AS validNum,
               SUM(
                       IFNULL(task_state IN (240, 242, 243, 244), 0)
                   )                         AS totalNum
        FROM u_patrol_result
        where execute_time BETWEEN #{startTime} and #{endTime}
        GROUP BY ${timeFlag}
order By ${timeFlag}
